create type role_type as enum ('CEO','Manager','Coach','Scout','Media','Player','Viewer');
create table organizations(id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz default now());
create table profiles(id uuid primary key references auth.users(id), org_id uuid references organizations(id), role role_type not null default 'Viewer', nick text, discord_id text unique, created_at timestamptz default now());
create table players(id uuid primary key default gen_random_uuid(), profile_id uuid references profiles(id), riot_id text, tracker_url text, city text, birth_date date, current_elo text, peak_elo text, main_roles text[], main_agents text[]);
create table tryouts(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), aim numeric, communication numeric, teamplay numeric, mentality numeric, adaptability numeric, clutch numeric, utility numeric, discipline numeric, final_score numeric generated always as ((aim+communication+teamplay+mentality+adaptability+clutch+utility+discipline)/8) stored, verdict text, vod_url text, clips jsonb, notes text, created_at timestamptz default now());
create table stats(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), acs numeric, adr numeric, kd numeric, hs numeric, wr numeric, fkfd numeric, kast numeric, clutch numeric, consistency numeric, collected_at date default current_date);
create table presence(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), schedule_id uuid, status text check(status in ('present','late','absent')), source text default 'manual', occurred_at timestamptz default now());
create table payments(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), amount numeric not null, due_date date not null, paid_at timestamptz, status text check(status in ('open','paid','late')) default 'open');
create table warnings(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), reason text, points_delta integer default -10, created_at timestamptz default now());
create table awards(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), title text, points_delta integer default 10, created_at timestamptz default now());
create table schedules(id uuid primary key default gen_random_uuid(), org_id uuid references organizations(id), kind text check(kind in ('aula','scrim','treino','review')), starts_at timestamptz, ends_at timestamptz);
create table performance_scores(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), season_id uuid, presence_weight numeric, performance_weight numeric, discipline_weight numeric, communication_weight numeric, evolution_weight numeric, teamplay_weight numeric, score numeric, created_at timestamptz default now());
create table coach_notes(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), coach_id uuid references profiles(id), note text, mentality numeric, discipline numeric, created_at timestamptz default now());
create table promotions(id uuid primary key default gen_random_uuid(), player_id uuid references players(id), from_tier text, to_tier text, reason text, created_at timestamptz default now());
create table seasons(id uuid primary key default gen_random_uuid(), org_id uuid references organizations(id), name text, split text, starts_on date, ends_on date);
